import {dimensionGraphic,dimensionTitles,dimensionObservation} from './dimension-infographics.mjs?v=report-3';
import {responsePositionGraph,previewResponseDetail,categoryColors} from './response-graphs.mjs?v=report-3';
import {workbookDimensions,frequencyCounts} from './innerly-v1-model.mjs?v=mh-14';
import {displayLanguage,languageName} from './mental-language.mjs?v=mh-14';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const say=(l,en,hi)=>l==='hi'?hi:en;
export const FREE_DIMENSIONS=['dimension-1','dimension-5'];
function lockedIllustration(id,l){
 const example=Array.from({length:36},(_,i)=>(i*3+1)%5);
 return `<div class="wb-blurred-art" aria-hidden="true">${dimensionGraphic(example,id,l,true)}<div></div><div></div></div>`;
}
export function workbookReportPreview(report,l='en',selection={}){
 l=displayLanguage(l);const stats=frequencyCounts(report.answers),locked=workbookDimensions.filter(d=>!FREE_DIMENSIONS.includes(d.id));
 const date=new Date(report.createdAt).toLocaleDateString(l,{day:'numeric',month:'short',year:'numeric'});
 return `<section class="mh-report wb-report-preview rp-preview"><header class="wb-preview-heading"><span class="rp-completed"><span aria-hidden="true">✓</span>${say(l,'Your reflection is ready','आपकी reflection तैयार है')}</span><h1>${say(l,'You made time<br>for <em>yourself.</em>','आपने समय निकाला<br><em>अपने लिए।</em>')}</h1><p>${say(l,'Your thoughts, your relationships, your everyday moments. Let’s explore what you shared.','आपकी सोच, आपके रिश्ते, रोज़मर्रा के अनुभव। आइए, आपके जवाबों को समझें।')}</p><div class="wb-preview-meta"><span>${stats.answered} / 36 ${say(l,'answered','जवाब')}</span><span>6 ${say(l,'areas of reflection','पहलू')}</span><span>${date}</span></div><button class="mh-secondary wb-preview-full-link" data-action="unlock-preview">${say(l,'View my full report','मेरी पूरी रिपोर्ट देखें')} →</button></header>
 <div class="rp-section-heading"><div><span class="wb-eyebrow">${say(l,'YOUR FREE PREVIEW','आपका मुफ़्त PREVIEW')}</span><h2>${say(l,'Start with a little understanding.','खुद को समझने की एक शुरुआत।')}</h2></div><span>2 / 6</span></div><p class="rp-instruction">${say(l,'Select any question in a graph to explore your answer and a reflection prompt.','Graph में कोई सवाल चुनें। उसका जवाब और उससे जुड़ा reflection देखें।')}</p>
 <div class="wb-free-grid">${FREE_DIMENSIONS.map(id=>{const d=workbookDimensions.find(d=>d.id===id),selected=d.items.includes(selection[id])?selection[id]:d.items[0],detailId=`rp-detail-${id}`;return `<article class="wb-story-card wb-free-card" data-preview-card="${id}" style="--category:${categoryColors[d.index]}"><div class="rp-card-title"><i aria-hidden="true"></i><h2>${esc(dimensionTitles[d.index][l==='hi'?1:0])}</h2></div><p class="rp-observation">${esc(dimensionObservation(report.answers,id,l))}</p>${responsePositionGraph(report.answers,id,l,{selected,preview:true,detailId})}<div class="rp-detail" id="${detailId}" aria-live="polite">${previewResponseDetail(report.answers,selected,l)}</div></article>`;}).join('')}</div>
 <p class="wb-preview-note">${say(l,'Each marker is one of your answers. Higher frequency has a different meaning for each statement; it is not a better or worse score.','हर निशान आपका एक जवाब है। ज़्यादा frequency का अर्थ हर statement में अलग है; यह बेहतर या खराब score नहीं है।')}</p>
 <div class="wb-more-heading"><span class="wb-eyebrow">${say(l,'THERE’S MORE TO YOUR REFLECTION','खुद को और करीब से समझें')}</span><h2>${say(l,'See how the pieces come together.','सभी पहलुओं को साथ समझें।')}</h2></div><div class="wb-lock-field"><div class="wb-locked-grid">${locked.map(d=>`<article class="wb-locked-card"><h3>${esc(dimensionTitles[d.index][l==='hi'?1:0])}</h3>${lockedIllustration(d.id,l)}</article>`).join('')}</div><div class="wb-unlock-panel"><span class="wb-lock-symbol" aria-hidden="true">✧</span><h2>${say(l,'Keep your full reflection.','अपनी पूरी reflection साथ रखें।')}</h2><p>${say(l,'Every area. Every answer. A little more understanding to take with you.','हर पहलू। हर जवाब। खुद की थोड़ी और समझ, आपके साथ।')}</p><ul><li>${say(l,'Interactive graphs across all 6 areas','सभी 6 पहलुओं के interactive graphs')}</li><li>${say(l,'All 36 answers & reflection prompts','सभी 36 जवाब और reflection prompts')}</li><li>${say(l,'A complete report to save as PDF','पूरी report को PDF में सेव करें')}</li></ul><p class="rp-included">${locked.map(d=>esc(dimensionTitles[d.index][l==='hi'?1:0])).join(' · ')}</p><button class="mh-primary" data-action="report-offer">${say(l,'Unlock full report — $1','पूरी report खोलें — $1')} <span aria-hidden="true">→</span></button><p class="rp-price-note">${say(l,'One-time payment for this report. No subscription.','इस report के लिए एक बार भुगतान। कोई subscription नहीं।')}</p><div class="wb-skip-preview"><button class="mh-link" data-action="unlock-preview">${say(l,'Skip for now — view full report','अभी छोड़ें — पूरी report देखें')} <span aria-hidden="true">→</span></button><p>${say(l,'Free during development. No card needed.','Development के दौरान मुफ़्त। Card की ज़रूरत नहीं।')}</p></div><small>${say(l,'Payments coming soon.','भुगतान जल्द शुरू होंगे।')}</small></div></div><p class="wb-placeholder-note">${say(l,'Blurred illustrations preview the report format, not additional results.','धुंधले चित्र report का स्वरूप दिखाते हैं, अतिरिक्त नतीजे नहीं।')}</p><p class="mh-footnote">${say(l,'A self-reflection questionnaire, not a diagnosis.','खुद को समझने के सवाल, diagnosis नहीं।')} · ${say(l,'Question language','सवालों की भाषा')}: <bdi>${esc(languageName(report.language))}</bdi></p><div id="mh-report-status" class="mh-form-message" role="status"></div></section>`;
}
